            hand1.xAxis = hand1.xrInputSource.gamepad.axes[2];
            hand1.yAxis = hand1.xrInputSource.gamepad.axes[3];
            hand2.xAxis = hand2.xrInputSource.gamepad.axes[2];
            hand2.yAxis = hand2.xrInputSource.gamepad.axes[3];
